mod solution;

fn main() {
    let cases = [
    (r#"n=4 unions=(0,1),(1,2) checkpoint union=(2,3) rollback query=(0,3)"#, r#"false"#),
    (r#"n=3 unions=(0,1) checkpoint union=(1,2) rollback query=(0,1)"#, r#"true"#),
    (r#"
n=3 unions=(0,1) checkpoint union=(1,2) rollback query=(0,1)
"#, r#"true"#),
    (r#"  
n=4 unions=(0,1),(1,2) checkpoint union=(2,3) rollback query=(0,3)
  "#, r#"false"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS dsu-rollback");
}
